use super::*;
use crate::DomainError;

// Real git 2.56 output, generated by `testdata/blame.sh` (`sh blame.sh testdata`) in a temporary
// repo with `GIT_CONFIG_GLOBAL=/dev/null`, fixed authors and dates. The command is
// `git -c core.fsmonitor=false -c blame.ignoreRevsFile= blame --porcelain [<rev>] -- <path>`.

/// `new.txt` at HEAD: root commit (boundary, under the old name `old.txt`), rename, an edit,
/// a Latin-1 line, empty lines and no final newline.
const HEAD: &[u8] = include_bytes!("testdata/blame-head.bin");
/// The same file at `HEAD~1`.
const REV: &[u8] = include_bytes!("testdata/blame-rev.bin");
/// Without a revision on the modified worktree: a new first line and a last line that gained
/// its final newline are not committed yet.
const WORKTREE: &[u8] = include_bytes!("testdata/blame-worktree.bin");
/// A file named `odd<TAB>caf\xe9.txt`: `filename` is C-quoted.
const ODD_NAME: &[u8] = include_bytes!("testdata/blame-odd-name.bin");
/// An empty file: no output.
const EMPTY: &[u8] = include_bytes!("testdata/blame-empty.bin");

const ROOT: &str = "29f3354a82c624f5d2e8b184350ae47239c5aa61";
const EDIT: &str = "b6fb63de500305a82034f0526617adca0007be96";
const LATIN1: &str = "a93f631b150ad54c4c8955cc86569605b0710cd7";

fn oid(hex: &str) -> Oid {
    Oid::from_hex(hex.as_bytes()).expect("valid test oid")
}

fn texts(blame: &Blame) -> Vec<&[u8]> {
    blame.lines.iter().map(|l| l.text.as_bytes()).collect()
}

fn ids(blame: &Blame) -> Vec<Option<Oid>> {
    blame
        .lines
        .iter()
        .map(|l| l.commit.map(|c| blame.commits[c].id))
        .collect()
}

fn reason(input: &[u8]) -> String {
    match parse_blame(input) {
        Err(DomainError::InvalidGitOutput { command, reason }) => {
            assert_eq!(command, "blame");
            reason
        }
        other => panic!("expected an error, got {other:?}"),
    }
}

#[test]
fn reads_lines_and_commits_at_head() {
    let blame = parse_blame(HEAD).expect("valid blame");
    assert_eq!(
        texts(&blame),
        [
            &b"one"[..],
            b"TWO",
            b"",
            b"four",
            b"five",
            b"caf\xe9",
            b"",
            b"last"
        ]
    );
    let (root, edit, latin) = (Some(oid(ROOT)), Some(oid(EDIT)), Some(oid(LATIN1)));
    assert_eq!(
        ids(&blame),
        [root, edit, root, root, edit, latin, latin, latin]
    );
    let orig: Vec<u32> = blame.lines.iter().map(|l| l.orig_line).collect();
    assert_eq!(orig, [1, 2, 3, 4, 5, 6, 7, 8]);
    // Each commit once, in order of first appearance.
    let commit_ids: Vec<Oid> = blame.commits.iter().map(|c| c.id).collect();
    assert_eq!(commit_ids, [oid(ROOT), oid(EDIT), oid(LATIN1)]);
}

#[test]
fn root_commit_is_boundary_under_its_old_name() {
    let blame = parse_blame(HEAD).expect("valid blame");
    let root = &blame.commits[0];
    assert!(root.boundary);
    assert_eq!(root.path, RepoPath::from("old.txt"));
    assert_eq!(root.previous, None);
    assert_eq!(root.summary, "Root");
    assert_eq!(
        root.author,
        Signature {
            name: "Anna Author".into(),
            email: "anna@example.com".into(),
            time: 1_700_000_100,
            offset_min: 120,
        }
    );
    assert_eq!(
        root.committer,
        Signature {
            name: "Carlo Committer".into(),
            email: "carlo@example.com".into(),
            time: 1_700_000_100,
            offset_min: -330,
        }
    );
}

#[test]
fn previous_names_the_parent_and_path() {
    let blame = parse_blame(HEAD).expect("valid blame");
    let edit = &blame.commits[1];
    assert!(!edit.boundary);
    assert_eq!(edit.path, RepoPath::from("new.txt"));
    assert_eq!(
        edit.previous,
        Some((
            oid("44d1f3511a68f6e64a079ba2ce0960f8613f588c"),
            RepoPath::from("new.txt")
        ))
    );
    assert_eq!(blame.commits[2].author.name, "Renée");
    assert_eq!(blame.commits[2].summary, "Latin-1 line, no final newline");
}

#[test]
fn reads_a_revision() {
    let blame = parse_blame(REV).expect("valid blame");
    assert_eq!(texts(&blame), [&b"one"[..], b"TWO", b"", b"four", b"five"]);
    assert_eq!(blame.commits.len(), 2);
}

#[test]
fn uncommitted_lines_have_no_commit() {
    let blame = parse_blame(WORKTREE).expect("valid blame");
    assert_eq!(blame.lines.len(), 9);
    assert_eq!(blame.lines[0].commit, None);
    assert_eq!(blame.lines[0].text.as_bytes(), b"zero");
    assert_eq!(blame.lines[8].commit, None);
    assert_eq!(blame.lines[8].text.as_bytes(), b"last");
    // The all-zero id is not among the commits.
    let commit_ids: Vec<Oid> = blame.commits.iter().map(|c| c.id).collect();
    assert_eq!(commit_ids, [oid(ROOT), oid(EDIT), oid(LATIN1)]);
    // Original line numbers refer to the committed file.
    assert_eq!(blame.lines[1].orig_line, 1);
    assert_eq!(blame.lines[7].orig_line, 7);
}

#[test]
fn quoted_filename_keeps_the_bytes() {
    let blame = parse_blame(ODD_NAME).expect("valid blame");
    assert_eq!(blame.commits[0].path.as_bytes(), b"odd\tcaf\xe9.txt");
    assert_eq!(texts(&blame), [&b"x"[..]]);
}

#[test]
fn empty_file_gives_empty_blame() {
    assert!(EMPTY.is_empty());
    assert_eq!(parse_blame(EMPTY).expect("valid blame"), Blame::default());
}

#[test]
fn accepts_missing_final_newline_and_unknown_headers() {
    let mut input = HEAD.to_vec();
    assert_eq!(input.pop(), Some(b'\n'));
    let blame = parse_blame(&input).expect("valid blame");
    assert_eq!(blame.lines.len(), 8);

    let with_ignored =
        String::from_utf8_lossy(REV).replacen("boundary\n", "boundary\nignored\n", 1);
    assert_eq!(
        parse_blame(with_ignored.as_bytes()).expect("valid blame"),
        parse_blame(REV).expect("valid blame")
    );
}

#[test]
fn same_commit_under_another_name_is_a_separate_entry() {
    let input = format!(
        "{HEADERS}filename a.txt\n\tone\n{EDIT} 1 2 1\nprevious {ROOT} b.txt\nfilename b.txt\n\ttwo\n\
         {EDIT} 2 3 1\nfilename a.txt\n\tthree\n",
        HEADERS = format_args!(
            "{EDIT} 1 1 1\nauthor A\nauthor-mail <a@x>\nauthor-time 1\nauthor-tz +0000\n\
             committer C\ncommitter-mail <c@x>\ncommitter-time 2\ncommitter-tz -0100\nsummary S\n"
        ),
    );
    let blame = parse_blame(input.as_bytes()).expect("valid blame");
    assert_eq!(blame.commits.len(), 2);
    assert_eq!(blame.commits[1].path, RepoPath::from("b.txt"));
    assert_eq!(
        blame.commits[1].previous,
        Some((oid(ROOT), RepoPath::from("b.txt")))
    );
    let idx: Vec<Option<usize>> = blame.lines.iter().map(|l| l.commit).collect();
    assert_eq!(idx, [Some(0), Some(1), Some(0)]);
}

#[test]
fn rejects_malformed_output() {
    // Truncated: group line without its content.
    let head = String::from_utf8_lossy(HEAD);
    let first_group = head.lines().next().expect("a line");
    assert!(reason(format!("{first_group}\n").as_bytes()).contains("missing the content line"));
    // A commit seen for the first time without headers.
    assert!(reason(format!("{ROOT} 1 1 1\n\tx\n").as_bytes()).contains("without its headers"));
    // Lines out of order.
    let skipped = format!("{ROOT} 1 2 1\n");
    assert!(reason(skipped.as_bytes()).contains("final line 2 instead of 1"));
    // Not a group line.
    assert!(reason(b"hello\n").contains("not a group line"));
    // Missing mandatory header.
    let no_tz = String::from_utf8_lossy(REV).replacen("author-tz +0200\n", "", 1);
    assert!(reason(no_tz.as_bytes()).contains("missing header `author-tz`"));
    // Invalid time zone.
    let bad_tz = String::from_utf8_lossy(REV).replacen("author-tz +0200", "author-tz 0200", 1);
    assert!(reason(bad_tz.as_bytes()).contains("invalid `author-tz` header"));
}

#[test]
fn serializes_to_json() {
    let blame = parse_blame(ODD_NAME).expect("valid blame");
    let json = serde_json::to_value(&blame).expect("serializable");
    // Non-UTF-8 path as a byte array; it round-trips.
    assert!(json["commits"][0]["path"].is_array());
    let back: Blame = serde_json::from_value(json).expect("deserializable");
    assert_eq!(back, blame);
}
